def compute(vars):
    japan_stores = vars["v1"]
    worldwide_stores = vars["v2"]

    if worldwide_stores == 0:
        return None

    ratio = japan_stores / worldwide_stores
    percentage = ratio * 100

    return {
        "value": percentage,
        "trace": {
            "japan_stores": japan_stores,
            "worldwide_stores": worldwide_stores,
            "ratio": ratio,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "percentage"
            }
        }
    }
